import fs from 'node:fs/promises';import{db}from'./reply-runtime-20261015.mjs';const dir='artifacts/reply-review-20261019-weekend';const rows=JSON.parse(await fs.readFile(dir+'/pending.json'));const results=[];
for(const row of rows.filter(r=>/^Inbound SMS:\s*(STOP|Unsubscribe)\s*$/i.test(r.text||''))){const[last]=await db('market_touches',{contact_id:'eq.'+row.id,direction:'eq.inbound',order:'created_at.desc,id.desc',limit:'1'});if(!/^Inbound SMS:\s*(STOP|Unsubscribe)\s*$/i.test(last?.notes||''))continue;const updated=await db('market_contacts',{id:'eq.'+row.id},'PATCH',{do_not_contact:true,cross_channel_suppressed_at:new Date().toISOString(),cross_channel_suppression_reason:'recipient_explicit_stop_20261019',sequence_paused:true,sequence_paused_reason:'recipient_opt_out',next_follow_up:null,stage:'dnc',decision:'opted_out'});const cancelled=await db('sequence_jobs',{contact_id:'eq.'+row.id,status:'eq.pending'},'PATCH',{status:'cancelled',error:'Recipient requested no further contact'});results.push({name:row.name,contact_id:row.id,updated:updated.length,cancelled:cancelled.length,inbound:last.id});}
await fs.writeFile(dir+'/optouts-honored.json',JSON.stringify(results,null,2));console.log(JSON.stringify(results));
